# Headings are written in capitals in the templates; the design sets them in sentence case.
def sentence_case(fragment):
    plain = re.sub(r'<[^>]+>|&\w+;', '', fragment)
    if plain != plain.upper():
        return fragment
    out, start = [], True
    for part in re.split(r'(<[^>]+>)', fragment):
        if part.startswith('<') or not part.strip():
            out.append(part)
            continue
        text = part.lower()
        capital = lambda match: match.group(1) + match.group(2).upper()
        if start:
            text = re.sub(r'^(\W*)(\w)', capital, text, count=1)
        text = re.sub(r'([.!?]\s+)(\w)', capital, text)
        text = re.sub(r'\b(nasha|btm)\b', lambda match: match.group(0).upper(), text).replace('NASHA resto bar', 'NASHA Resto Bar')
        start = text.rstrip().endswith(('.', '!', '?'))
        out.append(text)
    return ''.join(out)

def page(filename, title, description, body):
    schema = json.dumps({'@context': 'https://schema.org', '@type': 'Restaurant', 'name': DATA['name'], 'telephone': PHONE, 'address': {'@type': 'PostalAddress', 'streetAddress': '5, 100 Feet Ring Road, BTM 2nd Stage', 'addressLocality': 'Bengaluru', 'addressRegion': 'Karnataka', 'postalCode': '560076', 'addressCountry': 'IN'}, 'servesCuisine': ['North Indian', 'Chinese', 'Pizza'], 'openingHoursSpecification': {'@type': 'OpeningHoursSpecification', 'dayOfWeek': ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'], 'opens': '12:00', 'closes': '01:00'}, 'hasMenu': DATA['menuUrl'], 'acceptsReservations': BOOK}, ensure_ascii=False)
    html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#151515"><meta name="description" content="{E(description)}"><meta property="og:title" content="{E(title)} | Nasha Resto Bar"><meta property="og:description" content="{E(description)}"><meta property="og:type" content="website"><title>{E(title)} | Nasha Resto Bar, BTM</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800&family=DM+Sans:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="pages.css"><script type="application/ld+json">{schema}</script><script src="script.js" defer></script><script src="site.js" defer></script></head><body>
{header(filename)}<main id="main">{body}</main>{footer()}</body></html>'''
    html = re.sub(r'(<h([123])\b[^>]*>)(.*?)(</h\2>)', lambda match: match.group(1) + sentence_case(match.group(3)) + match.group(4), html, flags=re.S)
    html = re.sub(r'<link rel="preconnect"[^>]*>', '', html)
    html = re.sub(r'<link href="https://fonts.googleapis.com/[^>]*>', '<link rel="stylesheet" href="fonts.css">', html)
    html = html.replace('Google Fonts supplies the typefaces and may receive standard connection information such as your IP address.', 'Typefaces and photographs are served directly from this website; viewing them does not connect your browser to a third-party font or image service.')
    (ROOT / filename).write_text(html, encoding='utf-8')

def intro(kicker, title, text, photo=None):
    words = f'<div class="page-intro section"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="intro-copy">{text}</p></div>'
    if not photo:
        return f'<section class="page-plain">{words}</section>'
    # The header photo is decoration behind the heading, so it carries no alt text.
    return f'<section class="page-hero"><img class="page-hero-photo" src="assets/{photo}.jpg" alt="" fetchpriority="high" width="1800" height="1200">{words}</section>'

