about = intro('OUR STORY / A NEIGHBOURHOOD KIND OF NIGHT', 'A LITTLE ESCAPE.<br><em>A LOT OF NASHA.</em>', 'For the catch-ups that run long and the plans that come together at the last minute.', 'nasha-0027')
about += f'''<section class="section editorial"><div class="editorial-photo">{image('nasha-0015','The Nasha lounge with curved leather booths around round tables')}<span>OUR PLACE / BTM 2ND STAGE</span></div><div class="editorial-copy"><p class="eyebrow">RIGHT HERE IN BTM 2ND STAGE</p><h2 data-live="about-heading">COME AS YOU ARE.<br>STAY A LITTLE LONGER.</h2><div data-live="about-body"><p>Nasha brings the restaurant and the bar together on 100 Feet Ring Road. Meet over lunch, settle in for dinner, or give your usual catch-up a change of scene.</p><p>North Indian favourites, Chinese food, pizza, and a selection from the bar make room for different cravings at the same table.</p></div><a class="underlined" href="menu.html">Find your favourites <span>↗</span></a></div></section><section class="section editorial chef" id="chef" hidden><div class="editorial-copy"><p class="eyebrow">FROM THE KITCHEN</p><h2 data-live="chef-name"></h2><div data-live="chef-bio"></div></div><div class="editorial-photo" data-live="chef-photo"></div></section><section class="section ambience" id="ambience" hidden><p class="eyebrow">THE AMBIENCE</p><div class="ambience-copy" data-live="ambience"></div><a class="underlined" href="gallery.html">Take a look around <span>↗</span></a></section><section class="section values"><p class="eyebrow">THE INGREDIENTS OF A GOOD EVENING</p><div class="feature-grid"><article class="feature-card"><span class="feature-number">01</span><h3>FOOD FIRST.</h3><p>Something to start with. Something to share. Something that makes you reach for another bite.</p></article><article class="feature-card"><span class="feature-number">02</span><h3>YOUR KIND OF COMPANY.</h3><p>Old friends, new stories, and one more reason to put the phone away.</p></article><article class="feature-card"><span class="feature-number">03</span><h3>A PLAN WITHOUT THE FUSS.</h3><p>A neighbourhood address, an easy call, and a table worth making time for.</p></article></div></section><section class="section reviews-layout" id="reviews"><div><p class="eyebrow">FROM OUR GUESTS</p><h2>HOW WAS<br>YOUR EVENING?</h2><p class="intro-copy">Tell us what you loved and what we can do better. Feedback is read by the team and may be published here once reviewed.</p><div class="review-links" data-live="review-links"></div><div class="review-grid stacked" data-live="reviews"></div></div><form class="event-form" data-form="review"><label>Your name<input name="name" maxlength="60" autocomplete="name" required></label><fieldset class="rating"><legend>Your rating</legend>{''.join(f'<label><input type="radio" name="rating" value="{n}" required><span>{n} ★</span></label>' for n in range(5, 0, -1))}</fieldset><label>Your feedback<textarea name="comment" rows="5" maxlength="800" required placeholder="The food, the service, the evening…"></textarea></label>{TRAP}<button type="submit" class="button orange">Send feedback <span aria-hidden="true">↗</span></button><p class="form-status" role="alert" hidden></p></form></section><section class="section instagram" id="instagram" hidden><div class="section-heading"><div><p class="eyebrow">ON INSTAGRAM</p><h2>LATELY AT NASHA.</h2></div><a class="underlined" data-live="instagram-link" target="_blank" rel="noopener noreferrer">Follow us <span>↗</span></a></div><div class="instagram-feed" data-live="instagram"><button class="button cream" id="load-instagram">Load Instagram posts ↗</button><p class="small-copy">Loading posts connects to Instagram.</p></div></section><section class="quote-panel"><span aria-hidden="true">✳</span><h2>THE BEST PART OF THE EVENING?<br>THE PEOPLE YOU SHARE IT WITH.</h2><a class="text-link" href="events.html">Bring everyone together ↗</a></section>'''
page('about.html', 'Our story', 'Meet Nasha Resto Bar, a neighbourhood restaurant and bar on 100 Feet Ring Road in BTM 2nd Stage, Bengaluru. Read guest feedback and share your own.', about + cta())

